CREATE TABLE carrier_sla_remediation_cases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,case_number text NOT NULL,corrective_action_id uuid NOT NULL REFERENCES carrier_corrective_actions(id) ON DELETE RESTRICT,carrier_service_id uuid NOT NULL,warehouse_id uuid NOT NULL,contract_id uuid REFERENCES carrier_contracts(id) ON DELETE SET NULL,shipment_id uuid REFERENCES shipments(id) ON DELETE SET NULL,claim_id uuid REFERENCES delivery_claims(id) ON DELETE SET NULL,invoice_id uuid REFERENCES carrier_freight_invoices(id) ON DELETE SET NULL,root_cause text NOT NULL,remediation_plan text NOT NULL,owner_id uuid NOT NULL REFERENCES users(id),due_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'open' CHECK(status IN('open','investigating','awaiting_carrier','resolved','verified','cancelled')),severity text NOT NULL DEFAULT 'high' CHECK(severity IN('normal','high','critical')),recurrence_count integer NOT NULL DEFAULT 0 CHECK(recurrence_count>=0),resolution_effectiveness numeric(5,2) CHECK(resolution_effectiveness BETWEEN 0 AND 100),resolved_at timestamptz,resolved_by uuid REFERENCES users(id),verified_at timestamptz,verified_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL REFERENCES users(id),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,case_number),UNIQUE(company_id,corrective_action_id),FOREIGN KEY(company_id,carrier_service_id) REFERENCES carrier_services(company_id,id),FOREIGN KEY(company_id,warehouse_id) REFERENCES warehouses(company_id,id));
CREATE TABLE carrier_sla_remediation_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,case_id uuid NOT NULL REFERENCES carrier_sla_remediation_cases(id) ON DELETE CASCADE,from_status text,to_status text NOT NULL,note text NOT NULL,evidence_reference text,actor_id uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX carrier_sla_remediation_queue_idx ON carrier_sla_remediation_cases(company_id,warehouse_id,status,due_at);CREATE INDEX carrier_sla_remediation_event_idx ON carrier_sla_remediation_events(company_id,case_id,created_at DESC);
CREATE VIEW carrier_sla_remediation_kpis WITH(security_invoker=true) AS SELECT company_id,warehouse_id,count(*) cases,count(*)FILTER(WHERE status NOT IN('verified','cancelled')) open_cases,count(*)FILTER(WHERE status NOT IN('verified','cancelled') AND due_at<now()) overdue_cases,count(*)FILTER(WHERE severity='critical' AND status NOT IN('verified','cancelled')) critical_cases,coalesce(avg(resolution_effectiveness)FILTER(WHERE status='verified'),0) average_effectiveness,coalesce(avg(extract(epoch FROM(coalesce(verified_at,now())-created_at))/86400)FILTER(WHERE status='verified'),0) average_resolution_days,sum(recurrence_count) recurrences FROM carrier_sla_remediation_cases GROUP BY company_id,warehouse_id;
ALTER TABLE carrier_sla_remediation_cases ENABLE ROW LEVEL SECURITY;ALTER TABLE carrier_sla_remediation_cases FORCE ROW LEVEL SECURITY;ALTER TABLE carrier_sla_remediation_events ENABLE ROW LEVEL SECURITY;ALTER TABLE carrier_sla_remediation_events FORCE ROW LEVEL SECURITY;CREATE POLICY tenant_carrier_sla_remediation_cases ON carrier_sla_remediation_cases USING(company_id=nullif(current_setting('app.company_id',true),'')::uuid) WITH CHECK(company_id=nullif(current_setting('app.company_id',true),'')::uuid);CREATE POLICY tenant_carrier_sla_remediation_events ON carrier_sla_remediation_events USING(company_id=nullif(current_setting('app.company_id',true),'')::uuid) WITH CHECK(company_id=nullif(current_setting('app.company_id',true),'')::uuid);
GRANT SELECT,INSERT,UPDATE,DELETE ON carrier_sla_remediation_cases,carrier_sla_remediation_events TO stockflow_app;GRANT SELECT ON carrier_sla_remediation_kpis TO stockflow_app;
